function resid = compute_physics_residual_features(row, cfg, SensorConfig, P, window_duration_s)
%COMPUTE_PHYSICS_RESIDUAL_FEATURES Measured-minus-expected residual (§36).
%
%   resid = COMPUTE_PHYSICS_RESIDUAL_FEATURES(row, cfg, SensorConfig, P,
%   window_duration_s) implements the physics-informed-residual idea:
%       residual = measured_feature - expected_physics_feature
%   where "expected" is generated by re-running the SAME physics/sensor
%   pipeline as generate_dataset.m but forced to the Healthy fault state
%   AND with sensor noise/bias zeroed out, at the SAME operating point
%   (N_rpm, load_frac). This isolates the feature deviation caused
%   specifically by the active fault, from a deterministic physics
%   reference — the residual an undegraded, noise-free version of this
%   exact operating point would have produced.
%
%   Only a compact residual feature subset is computed (kept small
%   deliberately — the point is to test whether ANY residual signal adds
%   value, not to duplicate the full feature set): resid_vib_rms,
%   resid_vib_kurtosis, resid_mcsa_rms, resid_mcsa_THD.
%
%   Inputs:
%     row               - one row of the dataset table (needs equipment,
%                          N_rpm, load_frac, vib_rms, vib_kurtosis,
%                          mcsa_rms, mcsa_THD)
%     cfg, SensorConfig, P - as elsewhere
%     window_duration_s  - must match the value used in generate_dataset.m
%
%   Output struct 'resid': resid_vib_rms, resid_vib_kurtosis,
%   resid_mcsa_rms, resid_mcsa_THD

    equipment = char(row.equipment);
    N_rpm = row.N_rpm;
    load_frac = row.load_frac;

    if strcmp(equipment, 'Pump')
        baseline = pump_model(N_rpm, load_frac, P);
    else
        baseline = fan_model(N_rpm, load_frac, P);
    end

    healthy_sigparams = struct('cavitation_C',0,'unbalance_U',0,'bearing_D',0, ...
                                'misalignment_M',0,'efficiency_D',0);
    MotorOut = motor_model(N_rpm, baseline.torque_Nm, P.Motor);
    bf = bearing_fault_frequencies(N_rpm, P.Bearing);

    % Noise-free sensor configs for a deterministic reference.
    AccelClean = SensorConfig.Accelerometer;
    AccelClean.noise_rms_g = 0; AccelClean.bias_g = 0;
    CurrentClean = SensorConfig.Current;
    CurrentClean.noise_rms_A = 0; CurrentClean.bias_A = 0;

    Fs_acc = SensorConfig.Accelerometer.Fs;
    t_acc  = (0:1/Fs_acc:window_duration_s - 1/Fs_acc)';
    x_expected = generate_vibration_signal(t_acc, bf.f_r, healthy_sigparams, bf, AccelClean);

    Fs_cur = SensorConfig.Current.Fs;
    t_cur  = (0:1/Fs_cur:window_duration_s - 1/Fs_cur)';
    i_expected = generate_current_signal(t_cur, MotorOut, healthy_sigparams, CurrentClean);

    x_cond = condition_vibration_signal(x_expected, Fs_acc, cfg);
    i_cond = condition_current_signal(i_expected, Fs_cur, cfg);

    vib_windows = segment_signal(x_cond, Fs_acc, window_duration_s, 0);
    cur_windows = segment_signal(i_cond, Fs_cur, window_duration_s, 0);

    vfeat_expected = extract_vibration_features(vib_windows{1}, Fs_acc, bf);
    mfeat_expected = extract_mcsa_features(cur_windows{1}, Fs_cur, MotorOut.f_line_Hz, MotorOut.f_r_Hz);

    resid.resid_vib_rms       = row.vib_rms - vfeat_expected.rms;
    resid.resid_vib_kurtosis  = row.vib_kurtosis - vfeat_expected.kurtosis;
    resid.resid_mcsa_rms      = row.mcsa_rms - mfeat_expected.rms;
    resid.resid_mcsa_THD      = row.mcsa_THD - mfeat_expected.THD;
end
